"""Explain actual fills, once-evaluated warning conditions and fatal branches."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1877': ('공책에 직접 같은 글자를 쓰는 일과 검사표만 바꾸는 일은 달라요. 이 함수는 실제 메모리 내용을 채워요.', '검사 추적을 거치지 않는 데이터 채우기와 unpoison을 구별합니다.', '네 칸에 1·2·3·4를 쓰고 앞 세 칸을 7로 채워 7·7·7·4로 바꾸세요.', ['memset은 메모리의 일정 범위를 같은 바이트 값으로 채우는 함수예요. s는 시작 주소, c는 채울 값, n은 바이트 수예요. 바이트는 메모리 크기를 세는 단위예요.', 'memset_no_sanitize_memory도 실제 내용을 채우는 함수예요. 예를 들어 네 바이트가 1·2·3·4이고 앞 세 바이트를 7로 채우면 7·7·7·4가 돼요. 검사 정보만 바꾸는 unpoison과 역할이 달라요.', 'CONFIG_KMSAN을 넣은 쪽의 본문은 return __memset(s, c, n)이에요. 앞에 밑줄 두 개가 붙은 도우미를 직접 사용해 KMSAN의 자동 추적 처리를 거치지 않도록 해요.', 'instrumentation은 검사에 필요한 코드를 추가하는 것을 뜻해요. 이 함수는 그 추적을 피하며 실제 메모리를 채우려는 용도예요. 본문에 kmsan_internal_unpoison_memory를 별도로 호출하는 줄은 없어요.', 'CONFIG_KMSAN을 넣지 않은 쪽에서는 일반 memset을 호출해요. 어느 쪽이든 실제 데이터를 채우는 목적은 같고, 이 inline 함수는 도우미의 반환값인 시작 주소를 돌려줘요.', '실제 값을 썼다는 이유만으로 KMSAN 검사표도 자동으로 준비됨 상태로 바뀌었다고 설명하면 안 돼요. 호출하는 코드는 추적 상태를 어떻게 유지할지 별도로 고려해야 해요. 이름의 no-sanitize가 아무 동작도 하지 않는다는 뜻은 아니에요.'], [('KMSAN을 넣은 쪽의 no-sanitize memset이 직접 부르는 함수는 무엇인가요?', ['kmsan_internal_unpoison_memory예요', '__memset예요'], '정답은 두 번째예요. 본문은 __memset을 호출하고 결과를 반환해요. 검사표의 준비 상태만 바꾸는 unpoison과 구별하세요.'), ('이 함수는 실제 데이터 바이트도 바꾸나요?', ['네. 지정한 범위를 같은 바이트 값으로 채워요', '아니요. 검사표만 바꿔요'], '정답은 첫 번째예요. 1·2·3·4의 앞 세 칸을 7로 채우면 7·7·7·4가 되는 작업이에요. 검사 추적을 피한다는 말이 실제 쓰기까지 생략한다는 뜻은 아니에요.')]), 'os1878': ('질문을 한 번 계산해 답을 메모해 두면, 나중에는 같은 질문을 다시 계산하지 않고 메모를 볼 수 있어요. 이 매크로도 조건 결과를 보관해요.', '조건을 한 번 평가하는 방식과 저장한 참·거짓 반환을 이해합니다.', 'counter 0에서 ++counter == 1을 한 번 계산해 true를 적고, 뒤의 if와 결과는 그 메모를 보도록 그리세요.', ['KMSAN_WARN_ON은 조건이 참이면 문제를 알리는 매크로예요. 매크로는 이름을 사용한 자리에 정해진 코드 조각을 펼치는 장치예요. 이 수업은 CONFIG_KMSAN을 넣은 쪽 정의를 읽어요.', '첫 줄은 const bool __cond = WARN_ON(cond)예요. 원래 조건 cond를 WARN_ON에 넘기고 그 결과를 참·거짓 값 __cond에 저장해요. bool은 참 또는 거짓을 담는 형식이고 const는 이 지역 값을 다시 바꾸지 않겠다는 표시예요.', '뒤의 if (unlikely(__cond))는 저장한 값을 확인해요. 원래 cond 표현을 다시 쓰지 않으므로 그 조건을 다시 계산하지 않아요. unlikely는 이런 조건이 드물 것이라는 최적화 힌트이며 참·거짓을 뒤집는 말은 아니에요.', 'counter가 0이고 cond가 ++counter == 1이라면 counter를 1로 늘리고 1과 같은지 한 번 비교해요. 이후 분기에서도 원래 증가식을 다시 실행하면 counter가 2가 될 수 있으므로 저장한 결과를 쓰는 차이가 중요해요.', '전체 모양은 ({ 여러 문장 })이라는 GNU C 확장 문법이에요. 여러 문장을 실행하고 마지막 표현식 값을 전체 결과로 사용하는 방식이에요. 이 매크로의 마지막은 __cond이므로 보관한 참·거짓을 돌려줘요.', '단, 설정에 따른 BUG 처리로 정상 실행이 중단되면 마지막 결과까지 도달하지 않을 수 있어요. 한 번 계산 예시는 정상적으로 계속되는 경로의 평가 의미를 설명해요. 실제 커널 경고를 발생시키는 실습 대신 종이 위에서 값 변화를 따라가세요.'], [('이 활성 매크로는 if를 만날 때마다 원래 cond를 다시 계산하나요?', ['네. 같은 증가식도 계속 다시 실행해요', '아니요. WARN_ON의 결과를 저장하고 뒤에서는 그 값을 써요'], '정답은 두 번째예요. 원래 cond와 저장한 __cond는 역할이 달라요. 예시의 counter 증가는 한 번이며 if가 이를 다시 증가시키지 않아요.'), ('정상적으로 마지막까지 도달하면 매크로의 결과는 무엇인가요?', ['저장한 __cond의 참·거짓 값이에요', '조건과 상관없이 항상 0이에요'], '정답은 첫 번째예요. GNU C 문장 표현식의 마지막 값이 결과예요. 끝의 __cond를 보면 어느 값이 반환되는지 알 수 있어요.')]), 'os1879': ('고장 표시가 뜬 검사기를 꺼 두는 것과, 검사기를 부른 작업을 즉시 끝내는 것은 달라요. 상태 변경과 실행 흐름을 따로 봐요.', '실제 경고의 전역 비활성화와 호출자 반환을 구별합니다.', '조건 거짓→상태 유지, 조건 참→kmsan_enabled=false를 쓰세요. 호출자 return은 별도 조건으로 표시하세요.', ['kmsan_enabled는 KMSAN이 켜져 있는지를 담는 전역 상태예요. 전역은 여러 코드가 함께 참조하는 상태라는 뜻이에요. KMSAN_WARN_ON의 활성 정의는 경고 조건이 참일 때 이 상태를 false로 바꿔요.', '실제 문장은 WRITE_ONCE(kmsan_enabled, false)예요. WRITE_ONCE는 지정한 값의 메모리 쓰기를 컴파일러가 불필요하게 나누거나 반복하는 등의 변형으로부터 보호하려는 도우미예요. 한 번만 평생 변경할 수 있다는 뜻은 아니에요.', '이 도우미만으로 모든 동시 실행 순서가 해결되거나 잠금이 생기는 것은 아니에요. 여기서 읽을 핵심은 경고가 켜짐 상태에 false를 쓴다는 점이에요. true로 자동 복구하는 문장이 아니에요.', '조건이 거짓이면 이 분기를 지나지 않으므로 이 매크로가 enabled 값을 바꾸지 않아요. 이미 꺼져 있었다면 거짓 조건이 검사를 다시 켜 주지도 않아요.', '매크로 안에는 호출한 함수에서 곧바로 돌아가는 return이 없어요. 경고 뒤 실행이 계속되면 호출자 다음 문장도 이어질 수 있어요. 별도의 BUG 설정이나 호출자가 결과를 이용한 if-return 등은 따로 확인해야 해요.', '실습 모형에서 경고 횟수만 1 늘렸다면 실제 전역 비활성화까지 재현한 것은 아니에요. 실제 도우미의 enabled 검사와 현재 호출자의 후속 흐름을 함께 읽어야 상태 변경의 영향을 알 수 있어요.'], [('실제 활성 경고의 조건이 참이면 전역 상태에 무엇을 쓰나요?', ['kmsan_enabled를 언제나 true로 복구해요', 'kmsan_enabled에 false를 써요'], '정답은 두 번째예요. WRITE_ONCE의 두 번째 인자가 false예요. 경고 횟수만 늘리는 모형보다 실제 정책에 더 많은 동작이 있어요.'), ('이 경고 매크로가 모든 호출자의 본문을 자동 return으로 끝내나요?', ['아니요. 검사 상태 변경과 호출자 반환은 다른 일이에요', '네. 어느 함수든 그 자리에서 반드시 return해요'], '정답은 첫 번째예요. 매크로에 그런 return은 없어요. 실행이 이어질지 판단하려면 설정에 따른 중단과 호출자 코드를 따로 봐야 해요.')]), 'os1880': ('비상 설정 이름이 같아도 실제로 누르는 버튼은 상황마다 다를 수 있어요. 여기서는 panic 함수가 아니라 BUG 처리를 사용해요.', '경고 조건·중단 설정·실제 BUG 호출의 관계를 이해합니다.', '조건 참→검사 끄기→panic 설정 확인→설정 비영이면 BUG 순서를 그리세요.', ['KMSAN_WARN_ON의 활성 정의는 먼저 원래 조건 결과를 보관해요. 그 조건이 참인 분기 안에서 KMSAN을 끈 뒤 panic_on_kmsan 설정을 확인해요.', 'panic_on_kmsan이 0이 아니면 BUG()를 호출해요. 설정 이름에 panic이 들어 있어도 실제 이 매크로의 호출은 BUG예요. 조건 자체가 거짓이면 이 안쪽 설정 확인과 BUG 경로로 들어가지 않아요.', '원문 주석은 사용자 메모리 접근 관련 검사인 uaccess checks 때문에 이 자리에서 panic을 직접 호출할 수 없다고 설명해요. 호출 문맥에 제약이 있다는 뜻이에요. 주석보다 더 넓은 모든 상황의 이유를 추측해 붙이지 않아요.', '앞의 kmsan_report 끝부분은 보고 잠금을 푼 뒤 panic을 호출했어요. 이 경고 매크로는 같은 함수도 같은 위치도 아니므로 두 제어 흐름을 하나로 섞으면 안 돼요.', 'BUG는 정상적으로 돌아와 다음 일을 하도록 만든 API가 아니에요. 실제 실행에서는 오류 처리 경로로 넘어가므로 매크로 뒤 코드가 정상적으로 이어진다고 보장할 수 없어요.', '실습에서 BUG 대신 호출 사실만 적고 돌아오는 기록 함수를 썼다면 그 다음 코드가 실행될 수 있어요. 이는 모형이 관찰을 위해 돌아온 것이지 실제 BUG의 복귀 보증이 아니에요. 이 수업에서는 호출 전 순서와 조건을 종이에서 확인하세요.'], [('경고 조건이 참이고 panic 설정도 0이 아닐 때 이 매크로가 직접 호출하는 것은 무엇인가요?', ['항상 보고 함수 끝의 panic이에요', 'BUG예요'], '정답은 두 번째예요. 원문은 설정 확인 안에 BUG()를 적고 있어요. 설정 이름만 보고 실제 호출 함수까지 추측하면 안 돼요.'), ('돌아오는 BUG 기록 모형에서 다음 문장이 실행됐다면 실제 BUG도 정상 복귀한다고 말할 수 있나요?', ['아니요. 기록 모형의 반환과 실제 오류 경로는 달라요', '네. 모든 실제 커널에서도 반드시 정상 복귀해요'], '정답은 첫 번째예요. 모형은 관찰하기 위해 돌아오도록 만든 거예요. 호출 조건과 직전 순서를 확인한 결과를 실제 정상 복귀까지 검증한 것으로 넓히지 마세요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_465.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
